import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.Ki30n65y.js";const g=JSON.parse('{"title":"Database migrations","description":"","frontmatter":{},"headers":[],"relativePath":"install/database-migrations.md","filePath":"install/database-migrations.md"}'),n={name:"install/database-migrations.md"};function o(r,e,d,h,l,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="database-migrations" tabindex="-1">Database migrations <a class="header-anchor" href="#database-migrations" aria-label="Permalink to &quot;Database migrations&quot;">​</a></h1><p>DepGate upgrades its own database schema. This page explains what happens at startup and what it means for an upgrade, and gives contributors the rules for changing the schema. Operators only need the <a href="./operations#upgrade">upgrade procedure</a>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The schema comes from numbered SQL files that ship with every release, one ordered chain that only moves forward. At startup, before the server accepts requests, DepGate:</p><ol><li>Checks that PostgreSQL is 15 or later and that its migration files are present and unchanged.</li><li>Opens one transaction and takes a lock, so replicas that start together wait for each other.</li><li>Reads which migrations the database has run, applies the missing ones in order, and records each one.</li></ol><p>If anything fails, the transaction rolls back, the log names the migration and the SQL error, and the process exits. The database is exactly as it was, so the previous version can be started again.</p><p>The database records where it stands, so the release you come from never matters: you can skip releases, and a fresh install runs the whole chain.</p><h3 id="when-depgate-refuses-to-start" tabindex="-1">When DepGate refuses to start <a class="header-anchor" href="#when-depgate-refuses-to-start" aria-label="Permalink to &quot;When DepGate refuses to start&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Message</th></tr></thead><tbody><tr><td>A migration file changed after it was applied</td><td><code>Migration 0003_x has changed since it was applied. This DepGate build is broken; do not use it.</code></td></tr><tr><td>The database was upgraded by a newer DepGate</td><td><code>The database was upgraded by DepGate 0.3.0 (schema 0007). This is 0.2.0 (schema 0005). Start 0.3.0 or later.</code></td></tr><tr><td>A table is locked by an instance of an older version</td><td><code>A table is locked by another connection. Stop every DepGate instance running an older version, then start again.</code></td></tr></tbody></table><p>Nothing is changed in any of these cases.</p><h3 id="long-migrations" tabindex="-1">Long migrations <a class="header-anchor" href="#long-migrations" aria-label="Permalink to &quot;Long migrations&quot;">​</a></h3><p>A migration that rewrites a large table runs inside the startup transaction, and DepGate is unavailable until it finishes. The release notes name any migration expected to take more than a minute. The Kubernetes manifests allow 10 minutes for startup; raise the startup probe&#39;s <code>failureThreshold</code> when the release notes say so. With Compose, nothing interrupts a long migration.</p><h2 id="for-contributors" tabindex="-1">For contributors <a class="header-anchor" href="#for-contributors" aria-label="Permalink to &quot;For contributors&quot;">​</a></h2><p>Schema changes are plain SQL files in <code>packages/backend/migrations/</code>, named <code>NNNN_snake_case_name.sql</code> with contiguous numbers. TypeORM never changes the schema; it is only asked to draft SQL for review.</p><ol><li><p>Change the entity. Every index, unique, primary key and foreign key needs an explicit name (<code>idx_…</code>, <code>uq_…</code>, <code>pk_…</code>, <code>fk_…</code>) in the entity and in the migration.</p></li><li><p>Create the next file and draft its SQL:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migration:new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add_policy_owner</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=@depgate/backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migration:draft</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=@depgate/backend</span></span></code></pre></div><p>The draft is printed, never applied. Paste it into the new file and add what TypeORM cannot know, such as a backfill.</p></li><li><p>Start the backend (<code>npm run dev:backend</code>); it applies the migration. Run the integration tests, which include a drift test that fails when the entities and the migrations disagree.</p></li></ol><p>Rules that CI enforces:</p><ul><li>A migration on <code>main</code> is never edited; a mistake is fixed with a new one.</li><li>Everything runs in one transaction: no <code>BEGIN</code> or <code>COMMIT</code>, nothing <code>CONCURRENTLY</code>, no <code>VACUUM</code>, no <code>ALTER TYPE … ADD VALUE</code>.</li><li>Plain SQL only, with no dependency on application code.</li></ul><p>When two branches add the same number, the one that merges second renumbers its file. A development database that already ran the old number is re-adopted with <code>npm run db:adopt --workspace=@depgate/backend -- --readopt</code> (in development only), or reset.</p><p>At the 1.0 release the chain is squashed once into a single baseline. From then on it is permanent, and every older release upgrades straight to the latest.</p>`,19)])])}const m=a(n,[["render",o]]);export{g as __pageData,m as default};
